using System;
using System.Linq;
using System.Reflection;
using MDPro3;
using MDPro3.BattleSpirits;
using MDPro3.Servant;
using MDPro3.UI;
using MDPro3.UI.ServantUI;
using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.UI;
using TMPro;
using App=MDPro3.Program;

internal static class Regression {
static int assertions;
static void Check(bool condition,string message){assertions++;if(!condition)throw new Exception(message);}
static T Component<T>(string name) where T:Component,new()=>new GameObject(name,typeof(T)).GetComponent<T>();
static void Invoke(object target,string method,params object[] args){var type=target.GetType();MethodInfo m=null;while(type!=null&&m==null){m=type.GetMethod(method,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.DeclaredOnly);type=type.BaseType;}if(m==null)throw new Exception("Missing method "+method);m.Invoke(target,args);}
static T Field<T>(object target,string name)=>(T)target.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(target);
static void Element<T>(ElementManager manager,string label) where T:Component,new()=>manager.Elements[label]=new GameObject(label,typeof(T));
static void Button(ElementManager manager,string label)=>manager.Elements[label]=new GameObject(label,typeof(SelectionButton),typeof(Selectable));
static ScrollRect Scroll(ElementManager manager){var scroll=Component<ScrollRect>("ScrollRect");scroll.content=Component<RectTransform>("Content");scroll.content.SetParent(scroll.transform);scroll.verticalScrollbar=Component<Scrollbar>("Scrollbar");scroll.verticalScrollbar.handleRect=Component<RectTransform>("Handle");((RectTransform)scroll.transform).sizeDelta=new Vector2(700,600);manager.Elements["ScrollRect"]=scroll.gameObject;return scroll;}
static GameObject SoloPrefab(){var go=new GameObject("Solo row",typeof(SelectionToggle_Solo),typeof(Selectable));var row=go.GetComponent<SelectionToggle_Solo>();Element<TextMeshProUGUI>(row.Manager,"Title");row.Manager.Elements["Title"].AddComponent<LayoutElement>();var nameArea=new GameObject("NameArea",typeof(HorizontalLayoutGroup));nameArea.transform.SetParent(go.transform);row.Manager.Elements["Title"].transform.SetParent(nameArea.transform);go.GetComponent<RectTransform>().sizeDelta=new Vector2(650,MDPro3.UI.PropertyOverride.PropertyOverrider.Mobile?152:122);Element<ArtRawImageHandler>(row.Manager,"Image");row.Manager.Elements["Image"].AddComponent<RawImage>();row.Manager.Elements["Image"].GetComponent<RectTransform>().sizeDelta=new Vector2(700,122);row.Manager.Elements["NumBadge"]=new GameObject("NumBadge");row.Manager.Elements["TextClear"]=new GameObject("TextClear");return go;}
static GameObject CutinPrefab(){var go=new GameObject("Cutin row",typeof(SelectionToggle_Cutin),typeof(Selectable));Element<TextMeshProUGUI>(go.GetComponent<SelectionToggle_Cutin>().Manager,"ButtonText");return go;}
static GameObject Prefab(Func<GameObject> factory)=>new("Prefab"){Factory=factory};
static int LiveRows(ScrollRect scroll)=>scroll.content.children.Count(x=>x.gameObject.activeSelf);
static void SetupSolo(){var controller=new SoloSelector();App.instance.solo=controller;var ui=Component<SoloSelectorUI>("Solo UI");Scroll(ui.Manager);Element<TextMeshProUGUI>(ui.Manager,"TextOverview");Button(ui.Manager,"ButtonDeck");Button(ui.Manager,"ButtonPlay");ui.Manager.Elements["ButtonPlay"].transform.SetParent(ui.transform);ui.Initialize(controller);controller.LoadBots();}
static void SetupCutin(){var controller=new CutinViewer();App.instance.cutin=controller;var ui=Component<CutinViewerUI>("Cutin UI");Scroll(ui.Manager);Element<TMP_InputField>(ui.Manager,"InputField");Button(ui.Manager,"ButtonAutoPlay");ui.Manager.Elements["Root"]=new GameObject("Root");Element<TextMeshProUGUI>(ui.Manager,"TextTitle");ui.Initialize(controller);controller.LoadCutins();}
static void Solo(){SetupSolo();var controller=App.instance.solo;var ui=controller.GetUI<SoloSelectorUI>();var scroll=ui.ScrollRect;
 Invoke(controller,"FirstLoadEvent");Invoke(controller,"ApplyShowArrangement",0);ui.Print();ui.Print();Check(Addressables.Loads["UI/ItemSolo.prefab"]==1,"Pending Solo Print started duplicate asset loads");
 Addressables.Complete("UI/ItemSolo.prefab",Prefab(SoloPrefab));var owner=ui.superScrollView;
 Check(scroll.verticalScrollbar.onValueChanged.listeners.Count==1,"Solo owns more than one scrollbar listener");Check(owner.items.Count==4,"Solo did not show four opponents");Check(owner.gameObjects.Count==4&&LiveRows(scroll)==4,"Solo left overlapping row instances");Check(owner.selected==0&&controller.lastSoloItem?.index==0,"Solo did not establish index zero selection");
 int initialStarts=BattleIntegration.Starts.Count;owner.selected=-1;ui.OnPlay();owner.selected=4;ui.OnPlay();Check(BattleIntegration.Starts.Count==initialStarts,"Invalid Solo selection launched an opponent");owner.selected=0;ui.OnPlay();Check(BattleIntegration.Starts.Last()==("Player Deck","Infernowing"),"First Solo Play did not launch selected opponent");
 var third=(SelectionToggle_Solo)owner.GetItemByIndex(2);third.SetToggleOn();Check(owner.selected==2,"Solo row toggle did not update selected index");ui.Print();Check(ReferenceEquals(owner,ui.superScrollView),"Solo replaced the scroll owner");Check(owner.selected==2&&controller.lastSoloItem.index==2,"Solo reprint lost selected opponent");Check(scroll.verticalScrollbar.onValueChanged.listeners.Count==1&&LiveRows(scroll)==4,"Solo reprint accumulated listeners or rows");ui.OnPlay();Check(BattleIntegration.Starts.Last().Opponent=="Armored Fish","Solo Play used stale opponent");
 var positions=owner.gameObjects.Select(x=>x.GetComponent<RectTransform>().anchoredPosition.y).ToArray();Check(positions.Distinct().Count()==4,"Solo rows share anchored positions");Check(Math.Abs(positions[1]-positions[0])>=122,"Solo row stride is shorter than desktop banner");
 var title=controller.lastSoloItem.Manager.GetElement<TextMeshProUGUI>("Title");Check(title.text=="Armored Fish","Solo row title not bound to selected catalog deck");Check(title.textWrappingMode==TextWrappingModes.Normal&&title.enableAutoSizing&&title.fontSizeMin>=22&&title.fontSizeMax<=26&&title.lineSpacing==0,"Solo title has no readable wrap bounds");Check(title.GetComponent<LayoutElement>().ignoreLayout&&((RectTransform)title.transform.parent).sizeDelta.y==64,"Solo title layout group still overrides runtime title area");ui.SelectOnRight();Check(ui.Manager.Elements["ButtonPlay"].GetComponent<Selectable>().SelectCount==1,"Solo right navigation missed preserved ButtonPlay object");
 foreach(var aspect in new[]{.6f,.7166667f,1f}){var crop=SelectionToggle_Solo.ArtworkViewport(aspect,700f/122f);Check(crop.width>0&&crop.height>0&&crop.x>=0&&crop.y>=0&&crop.x+crop.width<=1.0001f&&crop.y+crop.height<=1.0001f,"Solo artwork crop escaped source");Check(Math.Abs(crop.width*aspect/crop.height-700f/122f)<.001f,"Solo banner stretches source aspect");}
 Invoke(ui,"OnDestroy");Check(scroll.verticalScrollbar.onValueChanged.listeners.Count==0,"Solo destroy leaked scrollbar listener");
}
static void MobileSolo(){MDPro3.UI.PropertyOverride.PropertyOverrider.Mobile=true;SetupSolo();var ui=App.instance.solo.GetUI<SoloSelectorUI>();Addressables.Complete("UI/ItemSolo.prefab",Prefab(SoloPrefab));var rows=ui.superScrollView.gameObjects;Check(Math.Abs(rows[0].GetComponent<RectTransform>().anchoredPosition.y-rows[1].GetComponent<RectTransform>().anchoredPosition.y)>=152,"Mobile Solo row stride overlaps banners");var title=App.instance.solo.lastSoloItem.Manager.GetElement<TextMeshProUGUI>("Title");Check(((RectTransform)title.transform.parent).sizeDelta.y==76,"Mobile title area did not grow");Invoke(ui,"OnDestroy");MDPro3.UI.PropertyOverride.PropertyOverrider.Mobile=false;}
static void Cutin(){SetupCutin();var controller=App.instance.cutin;var ui=controller.GetUI<CutinViewerUI>();var scroll=ui.Manager.GetElement<ScrollRect>("ScrollRect");
 ui.Print();ui.Print("Pisketona");Check(Addressables.Loads["UI/ItemCutin.prefab"]==1,"Pending Cutin Print started duplicate asset loads");Addressables.Complete("UI/ItemCutin.prefab",Prefab(CutinPrefab));var owner=ui.superScrollView;
 Check(owner.items.Count==1&&owner.items[0].args[0]=="200","Cutin completion used stale search tasks");Check(owner.selected==0,"Cutin did not select first filtered item");Check(scroll.verticalScrollbar.onValueChanged.listeners.Count==1&&LiveRows(scroll)==1,"Cutin left overlapping lists");
 Check(ui.SelectedCode==200,"Cutin selected code did not follow filtered row");var image=Field<RawImage>(ui,"previewImage");Check(image!=null&&image.gameObject.activeSelf&&image.texture!=null,"Cutin selected standee preview is not visible");Check(!image.raycastTarget,"Cutin preview blocks input");Check(image.texture.name=="/test/boss-b.png","Cutin preview texture belongs to a different selected boss");Check(image.GetComponent<AspectRatioFitter>().aspectMode==AspectRatioFitter.AspectMode.FitInParent&&Math.Abs(image.GetComponent<AspectRatioFitter>().aspectRatio-2f/3f)<.001f,"Cutin preview texture stretches instead of fitting");var name=Field<TextMeshProUGUI>(ui,"previewName");Check(name.text=="Pisketona","Cutin preview title uses a different boss");ui.OnAutoPlay();Check(BattleIntegration.Previews.Last()=="boss-b","Cutin Auto Play ignored selected boss");
 ui.Print();Check(ReferenceEquals(owner,ui.superScrollView),"Cutin replaced scroll owner");Check(owner.items.Count==2,"Cutin list did not restore both explicit bosses");var first=(SelectionToggle_Cutin)owner.GetItemByIndex(0);first.SetToggleOn();Check(ui.SelectedCode==100,"Cutin toggle did not update selected preview code");Check(Field<TextMeshProUGUI>(ui,"previewName").text=="Ritenia","Cutin preview name did not follow toggle");controller.AutoPlay();Check(BattleIntegration.Previews.Last()=="boss-a","Controller Auto Play ignored selected code");Invoke(first,"OnClick");Check(BattleIntegration.Previews.Last()=="boss-a","Cutin row click did not dispatch selected boss");
 ui.Print("missing");Check(owner.items.Count==0&&ui.SelectedCode==0,"Empty Cutin filter retained a playable stale boss");Check(!image.gameObject.activeSelf,"Empty Cutin filter retained visible stale preview");int previews=BattleIntegration.Previews.Count;ui.OnAutoPlay();Check(BattleIntegration.Previews.Count==previews,"Empty Cutin filter played unrelated default boss");Check(scroll.verticalScrollbar.onValueChanged.listeners.Count==1,"Cutin filtering accumulated scrollbar listeners");Invoke(ui,"OnDestroy");Check(scroll.verticalScrollbar.onValueChanged.listeners.Count==0,"Cutin destroy leaked scrollbar listener");
}
static void FailureAndLateCompletion(){SetupSolo();var solo=App.instance.solo.GetUI<SoloSelectorUI>();Addressables.Complete("UI/ItemSolo.prefab",null,false);Check(solo.superScrollView==null,"Failed Solo load installed unusable list");solo.Print();Invoke(solo,"OnDestroy");Addressables.Complete("UI/ItemSolo.prefab",Prefab(SoloPrefab));Check(solo.superScrollView==null,"Disposed Solo completed into a stale list");SetupCutin();var cutin=App.instance.cutin.GetUI<CutinViewerUI>();Addressables.Complete("UI/ItemCutin.prefab",null,false);Check(cutin.superScrollView==null&&cutin.SelectedCode==0,"Failed Cutin load retained a playable boss");cutin.Print();Invoke(cutin,"OnDestroy");Addressables.Complete("UI/ItemCutin.prefab",Prefab(CutinPrefab));Check(cutin.superScrollView==null,"Disposed Cutin completed into a stale list");}
public static int Main(){Solo();MobileSolo();Cutin();FailureAndLateCompletion();UnityEngine.Object.FlushDestroy();Console.WriteLine($"Solo/Cutin production handlers: {assertions} assertions passed.");return 0;}
}
